<?php namespace Workspace;
$stamp=static fn($time)=>$time===null?'—':gmdate('d.m.Y H:i:s',(int)$time);
$transitions=['initial'=>'Первая проверка','unchanged'=>'Без изменения','down'=>'Отказ','recovered'=>'Восстановление','legacy'=>'Снимок 0.1.0'];
$sources=['readiness'=>'API готовности','version_api'=>'API версии','panel_api'=>'API панели'];
?>
<p class="lede">Профиль стенда и результаты серверного опроса. Версии от API отделены от сведений оператора. Все отметки времени — UTC.</p>
<section class="panel"><div class="panelhead"><h2><?= h($stand['name']) ?></h2><span class="count"><?= count(array_filter($items,static fn($c)=>$c['configured'])) ?> / <?= count($items) ?></span></div>
<div class="inset"><p>Окружение: <b><?= h($stand['environment'] ?: 'Не задано') ?></b> · Ответственный: <b><?= h($stand['owner'] ?: 'Не задан') ?></b></p>
<?php if ($issues): ?><details><summary>Приёмка стенда: <?= count($issues) ?> замечаний</summary><ul><?php foreach ($issues as $issue): ?><li><?= h($issue) ?></li><?php endforeach ?></ul></details><?php else: ?><p>Показаны только доступные вам подключения. Полный отчёт приёмки доступен администратору установки через CLI.</p><?php endif ?></div></section>
<section class="panel"><div class="panelhead"><h2>Сервисы Workspace</h2><span class="count"><?= count($items) ?></span></div><div class="tablewrap"><table><thead><tr><th>Сервис и адреса</th><th>Ответственный</th><th>Версия / источник</th><th>Состояние и результат</th><th>Проверки, UTC</th></tr></thead><tbody>
<?php foreach ($items as $c): $r=$c['snapshot']; $latest=$c['latest']; $version=$c['last_version']; $success=$c['last_success']; ?><tr><td><b><?= h($c['label']) ?></b><small><?= h($c['id'].' · '.$c['purpose']) ?></small>
<?php if ($c['launch']): ?><small>Интерфейс: <a class="connection-url" href="<?= h($c['launch']) ?>" target="_blank" rel="noopener noreferrer"><?= h($c['launch']) ?></a></small><?php else: ?><small>Интерфейс: не задан</small><?php endif ?>
<small class="connection-url">API: <?= h($c['endpoint'] ?? 'не задан') ?></small>
<a href="?p=connections&amp;instance=<?= h($c['id']) ?>#protocol">Протокол проверок</a></td>
<td><?= h($c['owner'] ?: 'Не задан') ?><?php if ($c['type']==='github' && $success && $success['repository_owner']): ?><small>Владелец репозитория: <?= h($success['repository_owner']) ?></small><?php endif ?></td>
<td><?php if ($c['type']==='github'): ?>GitHub SaaS<small>REST API: <?= h($c['requested_api_version']) ?> (запрошенная версия)</small><?php else: ?>
<?php if ($version): ?><b><?= h($version['observed_version']) ?></b><small><?= h($sources[$version['version_source']] ?? 'API') ?> · <?= h($stamp($version['checked_at'])) ?><?php if (!$latest || $latest['id']!==$version['id'] || $c['status']!=='Доступно'): ?> · последняя известная<?php endif ?></small><?php else: ?>Не получена из API<?php endif ?>
<?php if ($c['installed_version']!==null): ?><small>По данным оператора: <?= h($c['installed_version']) ?><?php if ($version && $version['observed_version']!==$c['installed_version']): ?> · отличается от API<?php endif ?></small><?php endif ?>
<?php if ($latest && $latest['version_error']): ?><small><?= h($latest['version_error']) ?></small><?php endif ?><?php endif ?></td>
<td><span class="pill <?= $c['status']==='Доступно'?'done':($c['status']==='Ошибка'?'fail':'') ?>"><?= h($c['status']) ?></span><small><?= h($r['summary'] ?? '—') ?></small><?php if ($latest): ?><small><?= h($transitions[$latest['transition']]) ?> · HTTP <?= h($latest['http_status'] ?? '—') ?> · <?= $latest['duration_ms']!==null?h($latest['duration_ms'].' мс'):'—' ?></small><?php endif ?></td>
<td><small>Последняя: <?= h($stamp($r['checked_at'] ?? null)) ?></small><small>Успешная: <?= h($stamp($success['checked_at'] ?? null)) ?></small></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if ($instance!==null): ?><section class="panel" id="protocol"><div class="panelhead"><h2>Протокол: <?= h($items[$instance]['label']) ?></h2><a href="?p=connections">Закрыть</a></div>
<p class="inset">Последние 50 записей страницы. Старые адреса остаются в истории экземпляра; снимки 0.1.0 не содержат HTTP-метрик.</p>
<?php if (!$checks): ?><p class="inset">Проверок пока нет.</p><?php else: ?><div class="tablewrap"><table><thead><tr><th>Время / событие</th><th>Запрос</th><th>Результат</th><th>Версия</th></tr></thead><tbody>
<?php foreach ($checks as $check): ?><tr><td><?= h($stamp($check['checked_at'])) ?><small><?= h($transitions[$check['transition']]) ?></small></td><td class="connection-url"><?= h($check['method'] ?? '—') ?> <?= h($check['endpoint'] ?? '—') ?><small>HTTP <?= h($check['http_status'] ?? '—') ?> · <?= $check['duration_ms']!==null?h($check['duration_ms'].' мс'):'—' ?></small><?php if ($check['version_endpoint']): ?><small>GET <?= h($check['version_endpoint']) ?> · HTTP <?= h($check['version_http_status'] ?? '—') ?> · <?= h($check['version_duration_ms'] ?? '—') ?> мс</small><?php endif ?></td>
<td><span class="pill <?= $check['ok']?'done':'fail' ?>"><?= $check['ok']?'OK':'ERROR' ?></span><small><?= h($check['summary']) ?></small></td><td><?= h($check['observed_version'] ?? '—') ?><small><?= h($sources[$check['version_source'] ?? ''] ?? $check['version_error'] ?? '') ?></small></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<div class="inset"><a href="?p=connections&amp;instance=<?= h($instance) ?>#protocol">К новым записям</a><?php if ($nextBefore!==null): ?> · <a href="?p=connections&amp;instance=<?= h($instance) ?>&amp;before=<?= $nextBefore ?>#protocol">Более ранние записи</a><?php endif ?></div></section><?php endif ?>
